// Initialize an IPv4 socket address
void setup_addr(struct sockaddr_in *addr, const char *ip, int port) {
    // Zero all fields (clears sin_zero padding)
    memset(addr, 0, sizeof(*addr));

    // Set address family
    addr->sin_family = AF_INET;

    // Convert port to network byte order
