#include <stdio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <string.h>
#include <unistd.h>

#define PORT 8080
#define BACKLOG 10

int main() {
    int listenfd, connfd;
    struct sockaddr_in servaddr, cliaddr;
    socklen_t clilen = sizeof(cliaddr);
    char buf[1024];

    // Step 1: Create socket
    listenfd = socket(AF_INET, SOCK_STREAM, 0);
    if (listenfd < 0) { perror("socket"); return 1; }

    // Step 2: Bind to address/port
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_addr.s_addr = INADDR_ANY;  // All interfaces
    servaddr.sin_port = htons(PORT);
    if (bind(listenfd, (struct sockaddr*)&servaddr, sizeof(servaddr)) < 0) {
        perror("bind"); return 1;
    }

    // Step 3: Mark as passive (listening)
    listen(listenfd, BACKLOG);
    printf("Server listening on port %d...\n", PORT);

    // Step 4: Accept loop
    while (1) {
        // accept() blocks until client connects
        connfd = accept(listenfd, (struct sockaddr*)&cliaddr, &clilen);
        if (connfd < 0) { perror("accept"); continue; }

        // Read request and echo it back
        int n = read(connfd, buf, sizeof(buf) - 1);
        buf[n] = '\0';
        write(connfd, buf, n);

        close(connfd);  // Close THIS connection (not the listen socket)
    }
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

#define SERVER_IP "127.0.0.1"
#define SERVER_PORT 8080

int main() {
    int sockfd;
    struct sockaddr_in servaddr;
    char buf[1024];
    int n;

    // Step 1: Create TCP socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) { perror("socket"); return 1; }

    // Step 2: Set server address
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr);

    // Step 3: Connect to server (blocks until handshake done)
    if (connect(sockfd, (struct sockaddr*)&servaddr, sizeof(servaddr)) < 0) {
        perror("connect"); return 1;
    }
    printf("Connected to server!\n");

    // Step 4: Send message
    const char *msg = "Hello, server!";
    write(sockfd, msg, strlen(msg));

    // Step 5: Receive response
    n = read(sockfd, buf, sizeof(buf) - 1);
    buf[n] = '\0';
    printf("Server replied: %s\n", buf);

    // Step 6: Close connection
    close(sockfd);
    return 0;
}

#include <stdio.h>
#include <sys/socket.h>
#include <unistd.h>
#include <string.h>

int main() {
    int sv[2];  // Socket pair: sv[0]=parent end, sv[1]=child end
    char buf[100];

    // Create connected socket pair
    if (socketpair(AF_UNIX, SOCK_STREAM, 0, sv) < 0) {
        perror("socketpair"); return 1;
    }

    pid_t pid = fork();
    if (pid < 0) { perror("fork"); return 1; }

    if (pid == 0) {
        // Child process: uses sv[1]
        close(sv[0]);  // Close parent's end

        // Receive message from parent
        int n = read(sv[1], buf, sizeof(buf) - 1);
        buf[n] = '\0';
        printf("Child received: %s\n", buf);

        // Send reply
        write(sv[1], "Hello from child!", 17);
        close(sv[1]);

    } else {
        // Parent process: uses sv[0]
        close(sv[1]);  // Close child's end

        // Send message to child
        write(sv[0], "Hello from parent!", 18);

        // Receive reply
        int n = read(sv[0], buf, sizeof(buf) - 1);
        buf[n] = '\0';
        printf("Parent received: %s\n", buf);

        close(sv[0]);
        wait(NULL);
    }
    return 0;
}

#include <sys/socket.h>
#include <netinet/in.h>
#include <stdio.h>

// Enable SO_REUSEADDR to avoid "Address already in use" after restart
void set_reuse_addr(int sockfd) {
    int optval = 1;
    setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &optval, sizeof(optval));
}

// Safe read that retries on EINTR
int safe_read(int fd, void *buf, size_t count) {
    int n;
    do {
        n = read(fd, buf, count);
    } while (n < 0 && errno == EINTR);
    return n;
}
